1	interface Item {
2	  type: string;
3	  cursed?: boolean;
4	  enchantment?: number;
5	}
6	
7	interface QuoteStep {
8	  op: "quote";
9	  items: Item[];
10	}
11	
12	interface Damage {
13	  itemType: string;
14	  amount: number;
15	}
16	
17	interface ClaimStep {
18	  op: "claim";
19	  policy: number;
20	  incident: { cause: string; damages: Damage[] };
21	}
22	
23	type Step = QuoteStep | ClaimStep;
24	
25	interface Scenario {
26	  customer: { yearsWithMHPCO: number };
27	  steps: Step[];
28	}
29	
30	interface QuoteResult {
31	  premium: number;
32	}
33	
34	interface ClaimResult {
35	  payout: number;
36	  remainingCap: number;
37	}
38	
39	type StepResult = QuoteResult | ClaimResult;
40	
41	const BASE_PREMIUM: Record<string, number> = {
42	  sword: 100,
43	  amulet: 60,
44	  staff: 80,
45	  potion: 40,
46	  rune: 25,
47	};
48	
49	// The item types the office insures, mapped to their insured value. Doubles as
50	// the registry of "known" types for quote validation (isKnownType) and as the
51	// basis for a policy's cap (insuranceSum).
52	const INSURANCE_VALUE: Record<string, number> = {
53	  sword: 1000,
54	  amulet: 600,
55	  staff: 800,
56	  potion: 400,
57	  rune: 250,
58	  moonstone: 250,
59	};
60	
61	const PROCESSING_FEE = 5;
62	const FIRST_INSURANCE_SURCHARGE = 0.1;
63	
64	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
65	const COMPONENT_UNIT_PREMIUM = 25;
66	const COMPONENT_BLOCK_SIZE = 3;
67	const COMPONENT_BLOCK_PREMIUM = 60;
68	
69	const componentGroupBase = (count: number): number =>
70	  count === COMPONENT_BLOCK_SIZE
71	    ? COMPONENT_BLOCK_PREMIUM
72	    : count * COMPONENT_UNIT_PREMIUM;
73	
74	const componentsBase = (components: Item[]): number => {
75	  const countsByType = new Map<string, number>();
76	  for (const component of components) {
77	    countsByType.set(component.type, (countsByType.get(component.type) ?? 0) + 1);
78	  }
79	  return [...countsByType.values()].reduce(
80	    (total, count) => total + componentGroupBase(count),
81	    0,
82	  );
83	};
84	
85	const isComponent = (item: Item): boolean =>
86	  COMPONENT_TYPES.has(item.type);
87	
88	const itemsBase = (items: Item[]): number => {
89	  const mainBase = items
90	    .filter((item) => !isComponent(item))
91	    .reduce((sum, item) => sum + BASE_PREMIUM[item.type], 0);
92	  return mainBase + componentsBase(items.filter(isComponent));
93	};
94	
95	const CURSE_SURCHARGE = 0.5;
96	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
97	const HIGH_ENCHANTMENT_THRESHOLD = 5;
98	
99	// Sum `rate * base premium` for every item matching `applies`. The additive
100	// per-item form keeps each surcharge a flat term so quotePremium stays additive
101	// (see the float-drift note there).
102	const itemSurcharge = (
103	  items: Item[],
104	  applies: (item: Item) => boolean,
105	  rate: number,
106	): number =>
107	  items.reduce(
108	    (sum, item) => sum + (applies(item) ? BASE_PREMIUM[item.type] * rate : 0),
109	    0,
110	  );
111	
112	const curseSurcharge = (items: Item[]): number =>
113	  itemSurcharge(items, (item) => item.cursed === true, CURSE_SURCHARGE);
114	
115	const highEnchantmentSurcharge = (items: Item[]): number =>
116	  itemSurcharge(
117	    items,
118	    (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
119	    HIGH_ENCHANTMENT_SURCHARGE,
120	  );
121	
122	const LOYALTY_DISCOUNT = 0.2;
123	const LOYALTY_THRESHOLD_YEARS = 2;
124	const FOLLOWUP_DISCOUNT = 0.15;
125	
126	const loyaltyDiscount = (base: number, yearsWithMHPCO: number): number =>
127	  yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS ? base * LOYALTY_DISCOUNT : 0;
128	
129	const followupDiscount = (base: number, isFollowup: boolean): number =>
130	  isFollowup ? base * FOLLOWUP_DISCOUNT : 0;
131	
132	// Always-on surcharge charged on every policy, expressed as a flat term so
133	// quotePremium stays additive (see the float-drift note there).
134	const firstInsuranceSurcharge = (base: number): number =>
135	  base * FIRST_INSURANCE_SURCHARGE;
136	
137	const isKnownType = (type: string): boolean => type in INSURANCE_VALUE;
138	
139	const assertKnownItems = (items: Item[]): void => {
140	  const unknown = items.find((item) => !isKnownType(item.type));
141	  if (unknown !== undefined) {
142	    throw new Error(`Unknown item type: ${unknown.type}`);
143	  }
144	};
145	
146	const quotePremium = (
147	  items: Item[],
148	  yearsWithMHPCO: number,
149	  isFollowup: boolean,
150	): number => {
151	  assertKnownItems(items);
152	  const base = itemsBase(items);
153	  const surcharges =
154	    firstInsuranceSurcharge(base) +
155	    curseSurcharge(items) +
156	    highEnchantmentSurcharge(items);
157	  const discounts =
158	    loyaltyDiscount(base, yearsWithMHPCO) + followupDiscount(base, isFollowup);
159	  // Sum flat terms rather than scaling `base * (1 + rate)`: the additive form
160	  // avoids IEEE-754 drift that would otherwise round wrong under Math.ceil.
161	  return Math.ceil(base + surcharges - discounts + PROCESSING_FEE);
162	};
163	
164	const DEDUCTIBLE = 100;
165	const CAP_MULTIPLIER = 2;
166	const HIGH_ENCHANTMENT_CLAIM_THRESHOLD = 8;
167	const HIGH_ENCHANTMENT_REIMBURSEMENT = 0.5;
168	
169	const insuranceSum = (items: Item[]): number =>
170	  items.reduce((sum, item) => sum + INSURANCE_VALUE[item.type], 0);
171	
172	// Reimbursement for a single damage before the deductible. Items enchanted to
173	// level 8+ are reimbursed at only 50% of the damage amount.
174	const reimbursement = (item: Item, amount: number): number =>
175	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_THRESHOLD
176	    ? amount * HIGH_ENCHANTMENT_REIMBURSEMENT
177	    : amount;
178	
179	// The policy item a damage refers to, matched by type. Throws if the damage
180	// references an item the policy does not cover.
181	const policyItemFor = (damage: Damage, policyItems: Item[]): Item => {
182	  const item = policyItems.find((i) => i.type === damage.itemType);
183	  if (item === undefined) {
184	    throw new Error(`Item not in policy: ${damage.itemType}`);
185	  }
186	  return item;
187	};
188	
189	// Each damaged item is reimbursed (subject to clauses) less one deductible,
190	// floored in MHPCO's favor.
191	const damagesPayout = (damages: Damage[], policyItems: Item[]): number =>
192	  Math.floor(
193	    damages.reduce((sum, damage) => {
194	      const item = policyItemFor(damage, policyItems);
195	      return sum + (reimbursement(item, damage.amount) - DEDUCTIBLE);
196	    }, 0),
197	  );
198	
199	const claimResult = (
200	  claim: ClaimStep,
201	  policyItems: Item[],
202	  remainingCap: number,
203	): ClaimResult => {
204	  const desired = damagesPayout(claim.incident.damages, policyItems);
205	  const payout = Math.min(desired, remainingCap);
206	  return { payout, remainingCap: remainingCap - payout };
207	};
208	
209	// A policy's cap starts at twice its insurance sum and is drawn down by each
210	// claim. remainingCapByPolicy tracks the running balance keyed by policy step
211	// index, seeding the initial cap the first time a policy is claimed against.
212	const countByType = (types: string[]): Map<string, number> => {
213	  const counts = new Map<string, number>();
214	  for (const type of types) {
215	    counts.set(type, (counts.get(type) ?? 0) + 1);
216	  }
217	  return counts;
218	};
219	
220	// A claim may not report more damages of a type than the policy insures.
221	const assertDamagesWithinPolicy = (claim: ClaimStep, policyItems: Item[]): void => {
222	  const insured = countByType(policyItems.map((item) => item.type));
223	  const damaged = countByType(claim.incident.damages.map((damage) => damage.itemType));
224	  for (const [type, count] of damaged) {
225	    if (count > (insured.get(type) ?? 0)) {
226	      throw new Error(`Too many damages for item type: ${type}`);
227	    }
228	  }
229	};
230	
231	const settleClaim = (
232	  claim: ClaimStep,
233	  steps: Step[],
234	  remainingCapByPolicy: Map<number, number>,
235	): ClaimResult => {
236	  const policyItems = (steps[claim.policy] as QuoteStep).items;
237	  assertDamagesWithinPolicy(claim, policyItems);
238	  const remainingCap =
239	    remainingCapByPolicy.get(claim.policy) ??
240	    CAP_MULTIPLIER * insuranceSum(policyItems);
241	  const result = claimResult(claim, policyItems, remainingCap);
242	  remainingCapByPolicy.set(claim.policy, result.remainingCap);
243	  return result;
244	};
245	
246	export const runScenario = (scenario: Scenario): { results: StepResult[] } => {
247	  const remainingCapByPolicy = new Map<number, number>();
248	  const results = scenario.steps.map((step, index): StepResult => {
249	    if (step.op === "claim") {
250	      return settleClaim(step, scenario.steps, remainingCapByPolicy);
251	    }
252	    // Every quote after the first is a follow-up contract; the map index is
253	    // already the count of quotes seen so far, so no separate counter is needed.
254	    const isFollowup = index > 0;
255	    return {
256	      premium: quotePremium(step.items, scenario.customer.yearsWithMHPCO, isFollowup),
257	    };
258	  });
259	  return { results };
260	};
